Hier ist ein C++ Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes in der Datei zählt:

```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string word; // Wort, nach dem gesucht werden soll
    int count = 0; // Anzahl der Vorkommen des Wortes

    // Wort von Benutzer einlesen
    cout << "Geben Sie das Suchwort ein: ";
    getline(cin, word);

    string line;
    ifstream file("dateiname.txt"); // Dateiname zu ändern

    if (!file) {
        cerr << "Fehler beim Öffnen der Datei." << endl;
        return 1;
    }

    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            count++; // Wort gefunden, Anzahl erhöhen
            pos += word.length(); // Start des nächsten Suchvorgangs setzen
        }
    }

    file.close();

    cout << "Das Wort '" << word << "' kommt " << count << " Mal in der Datei vor." << endl;

    return 0;
}
```

Erklärung:

1. Das Programm erfordert die Einbindung der Standardbibliotheken `<iostream>`, `<fstream>` und `<string>`.

